import {recipeArt} from './recipe-art.js';
import {activityOutcomeMarkup,mountActivityOutcome} from '../activity-outcome.js';
import {RECIPES,recipeById,initialCooking,reduceCooking,evaluateCooking,cookingSave,validateCookingSave} from './cooking-model.js';
import {createCookingSession,createCookingViewport} from './cooking-view.js';
const BODY=`<div id="cooking-panel" class="cooking-panel"><p class="cook-invitation">한 컵, 한 바퀴. 나만의 맛을 찾아요.</p><nav class="cook-recipes" aria-label="레시피 선택">${RECIPES.map((r,i)=>`<button data-cook-action="recipe" data-id="${r.id}">${recipeArt(r.id)}<span><small>0${i+1} · ${['싱그럽게','노릇하게','따뜻하게'][i]}</small><strong>${r.name}</strong></span></button>`).join('')}</nav><ol id="cook-steps" class="cook-steps" aria-label="요리 순서"></ol><div class="cook-layout"><section class="cook-scene"><canvas id="cook-canvas" aria-label="주방에서 직접 계량하고 섞는 도름이"></canvas><p id="cook-render-note" hidden>입체 화면을 표시하지 못했어요. 창을 닫고 다시 열면 재료부터 이어갈 수 있어요.</p><div class="cook-notebook"><span class="cook-note-label">오늘의 레시피</span><h3 id="cook-title"></h3><p id="cook-guide"></p><p id="cook-concept"></p><p id="cook-formula"></p></div></section><section class="cook-controls"><p id="cook-status" role="status" aria-live="polite"></p><p id="cook-next" class="cook-next"></p><div id="cook-measure"><h3>같은 컵으로 계량해요</h3><div id="cook-ingredients"></div><p id="cook-order"></p><div class="cook-row"><button data-cook-action="undo" id="cook-undo">마지막 한 컵 빼기</button><button data-cook-action="mix" id="cook-mix" class="primary" aria-describedby="cook-next">섞기 시작</button></div></div><div id="cook-stir" hidden><h3>원을 그리며 섞어요</h3><div id="cook-stir-pad" class="cook-stir-pad" tabindex="0" role="application" aria-label="섞기. 원을 따라 끌거나 방향키를 위 오른쪽 아래 왼쪽 순서로 눌러요"><span id="cook-turns"></span><span class="cook-dot"></span></div><div class="cook-quadrants" aria-label="버튼으로 원 돌기">${['위','오른쪽','아래','왼쪽'].map((x,i)=>`<button data-cook-action="quadrant" data-index="${i}" aria-label="${x}으로 섞기">${['↑','→','↓','←'][i]}</button>`).join('')}</div><p>원을 따라 끌거나 ↑ → ↓ ← 버튼을 돌아요. 오래 섞어도 결과가 달라져요.</p><button data-cook-action="heat" id="cook-heat" class="primary" aria-describedby="cook-next">가열판으로 옮기기</button><button data-cook-action="finish" id="cook-salad-finish" class="primary" aria-describedby="cook-next">이 상태로 담기</button></div><div id="cook-heating" hidden><h3>세기와 시간을 골라요</h3><div class="cook-row">${[1,2,3].map((n,i)=>`<button data-cook-action="level" data-value="${n}" aria-pressed="false">${['약하게','중간','강하게'][i]} · ${n}</button>`).join('')}</div><meter id="cook-energy" min="0" max="60" value="0" aria-label="쌓인 열"></meter><p id="cook-timer"></p><div class="cook-row"><button data-cook-action="resume" id="cook-resume" class="primary">가열 시작</button><button data-cook-action="pause" id="cook-pause">잠깐 멈춤</button><button data-cook-action="flip" id="cook-flip">한 번 뒤집기</button><button data-cook-action="finish" id="cook-finish" class="primary" aria-describedby="cook-next">지금 꺼내기</button></div></div><div id="cook-result" hidden><span class="cook-note-label">오늘의 한 그릇</span><h3 id="cook-result-title"></h3><p id="cook-result-text"></p><details class="cook-comparison-note"><summary>지난 요리와 비교하기</summary><p id="cook-comparison"></p></details></div>${activityOutcomeMarkup("cook-outcome")}<div class="cook-footer"><button data-cook-action="reset" id="cook-reset">한 번 더 만들기</button><p id="cook-save"></p><button data-cook-action="save" id="cook-save-retry" hidden>저장 다시 시도</button></div></section></div><details class="cook-help"><summary>요리가 달라지는 원리 · 저장 안내</summary><p>비율·순서·횟수·열의 세기와 시간을 비교하는 간단한 게임 모형이에요. 같은 선택은 같은 결과가 나와요. 실제 요리 온도·시간·안전 지침이나 영양 평가가 아니에요.</p><p>완성 전 초안과 직전 결과 한 개는 이 브라우저에 저장해요. 닫기·다른 화면·탭 숨기기는 가열을 멈춰요. 돌아와서 가열 시작을 눌러야 이어져요. 레시피를 바꾸면 이번 재료는 비워요.</p></details></div>`;
export function createCookingController({ui,getView,getActors=()=>null,getProgress=()=>({}),transact=()=>false,discover=()=>{},doc=globalThis.document,win=globalThis.window,reduced=false,createSession=createCookingSession,createViewport=createCookingViewport}){
 let live=null,temporary=null;const $=id=>doc.querySelector('#'+id);
 function bind(s,n,t,f){n.addEventListener(t,f);s.listeners.push([n,t,f]);}
 function release(s){const id=s.pointer;s.pointer=null;s.pointers.clear();if(id!==null)try{$('cook-stir-pad').releasePointerCapture(id);}catch{}}
 function save(s){const payload=cookingSave(s.state,s.previous);temporary=payload;const ok=transact({type:'SAVE_COOKING',cooking:payload});$('cook-save').textContent=ok?'만들던 요리와 지난 결과를 이 브라우저에 저장했어요':'저장하지 못했어요. 이번 초안은 페이지를 닫으면 사라질 수 있어요';$('cook-save-retry').hidden=ok;if(ok)temporary=null;return ok;}
 function close(){const s=live;if(!s)return;s.state=reduceCooking(s.state,{type:'PAUSE'});save(s);release(s);live=null;s.outcome?.dispose();for(const[n,t,f]of s.listeners)n.removeEventListener(t,f);s.viewport?.dispose();s.session?.dispose();}
 function render(s){if(live!==s)return;const st=s.state,r=recipeById(st.recipe),phase=st.phase;s.root.dataset.phase=phase;for(const b of s.root.querySelectorAll('[data-cook-action="recipe"]'))b.setAttribute('aria-pressed',String(b.dataset.id===st.recipe));for(const b of s.root.querySelectorAll('[data-cook-action="level"]'))b.setAttribute('aria-pressed',String(Number(b.dataset.value)===st.level));$('cook-title').textContent=r.name;$('cook-guide').textContent=r.guide;$('cook-concept').textContent=r.concept;const steps=[['measure','재료 담기'],['mix','섞기'],...(r.heat?[['heat','데우기']]:[]),['result','완성']];$('cook-steps').innerHTML=steps.map(([id,label],i)=>`<li${id===phase?' aria-current="step"':''}><span>${i+1}</span>${label}</li>`).join('');$('cook-formula').textContent=`내 비율 ${st.amounts.join(' : ')} · 총 ${st.order.length}컵 / 12컵 · ${st.turns.toFixed(2)}바퀴`;
  $('cook-measure').hidden=phase!=='measure';$('cook-stir').hidden=phase!=='mix';$('cook-heating').hidden=phase!=='heat';$('cook-result').hidden=phase!=='result';if(s.renderedRecipe!==st.recipe){$('cook-ingredients').innerHTML=r.ingredients.map((x,i)=>`<button data-cook-action="pour" data-index="${i}"><span class="cook-swatch" style="background:${r.colors[i]}"></span><span>${x}<strong></strong></span><small>＋ 한 컵</small></button>`).join('');s.renderedRecipe=st.recipe;}for(const b of $('cook-ingredients').querySelectorAll('[data-index]')){const i=Number(b.dataset.index);b.disabled=st.amounts[i]>=6||st.order.length>=12;b.querySelector('strong').textContent=`${st.amounts[i]}컵`;}$('cook-order').textContent=st.order.length?'담은 순서: '+st.order.map(i=>r.ingredients[i]).join(' → '):'재료를 고른 순서대로 한 컵씩 담아요';$('cook-undo').disabled=!st.order.length;$('cook-mix').disabled=!st.amounts.every(n=>n>0);$('cook-turns').textContent=st.turns.toFixed(2)+'바퀴';$('cook-stir-pad').style.setProperty?.('--turn',`${(st.quadrant??0)*90}deg`);$('cook-heat').hidden=!r.heat;$('cook-salad-finish').hidden=!!r.heat;$('cook-heat').disabled=$('cook-salad-finish').disabled=st.turns<1;
  $('cook-energy').value=Math.min(60,st.energy);$('cook-timer').textContent=`${st.seconds.toFixed(1)}초 · 쌓인 열 ${st.energy.toFixed(1)}칸${st.seconds>=45?' · 자동 멈춤':''}`;$('cook-resume').disabled=st.running||st.seconds>=45;$('cook-resume').textContent=st.seconds?'가열 이어가기':'가열 시작';$('cook-pause').disabled=!st.running;$('cook-flip').hidden=st.recipe!=='pancake';$('cook-flip').disabled=st.flipEnergy!==null||st.seconds<1;$('cook-flip').textContent=st.flipEnergy!==null?'뒤집었어요':'한 번 뒤집기';$('cook-finish').disabled=st.seconds<2;$('cook-reset').textContent='현재 재료 비우기';$('cook-reset').hidden=phase==='result';
  const status={measure:'1 · 재료와 비율을 골라요',mix:'2 · 손으로 섞은 만큼 변해요',heat:st.running?'3 · 변하는 색을 보고 꺼낼 때를 골라요':'3 · 가열은 멈춰 있어요',result:'한 그릇 완성!'};$('cook-status').textContent=status[phase];const missing=r.ingredients.filter((_,i)=>!st.amounts[i]);$('cook-next').textContent=phase==='measure'?(missing.length?`${missing.join('·')}도 한 컵 이상 담으면 섞을 수 있어요.`:'재료가 준비됐어요. 섞기 시작을 눌러요.'):phase==='mix'?(st.turns<1?'한 바퀴 이상 저으면 다음으로 갈 수 있어요.':`추천은 ${r.mix[0]}~${r.mix[1]}바퀴. 원하는 만큼 섞고 ${r.heat?'가열판으로 옮겨요.':'그릇에 담아요.'}`):phase==='heat'?(st.seconds<2?'가열 시작을 누르고 2초 이상 데우면 꺼낼 수 있어요.':'색을 보고 지금 꺼내기를 눌러요.'):'';$('cook-next').hidden=phase==='result';if(phase==='result'){const result=evaluateCooking(st);$('cook-result-title').textContent=result.title;$('cook-result-text').textContent=result.explanation+` 섞인 정도 ${result.smooth}/100.`;$('cook-comparison').textContent=s.previous?`직전 ${recipeById(s.previous.recipe).name}: ${s.previous.amounts.join(':')} · ${s.previous.turns.toFixed(2)}바퀴 · 열 ${s.previous.energy.toFixed(1)}칸 · 고르게 섞임 ${evaluateCooking(s.previous).smooth}/100`:'다음에는 한 가지 조건만 바꿔 결과를 비교해 봐요';}s.outcome?.update({show:phase==='result',title:'완성! 다음 요리도 해 볼까요?',detail:'',saveText:$('cook-save').textContent,next:{label:'다음 레시피',run:()=>apply(s,{type:'RECIPE',id:RECIPES[(RECIPES.indexOf(r)+1)%RECIPES.length].id})}});s.session?.update(st);s.viewport?.render();
 }
 function apply(s,a){if(live!==s||doc.hidden||s.renderFailed)return;const old=s.state,next=reduceCooking(old,a);if(next===old)return;s.state=next;if(old.phase==='result'&&next.phase==='measure')s.previous=old;if(a.type!=='TICK')save(s);if(next.phase==='result'&&old.phase!=='result')discover('home-cook');render(s);}
 function open(){if(live)return true;const view=getView();if(!view?.homeView)return false;return ui.workshop('도름이의 작은 주방',BODY,()=>{const saved=validateCookingSave(temporary??getProgress().homeCooking)??cookingSave(initialCooking()),s={state:saved.draft,previous:saved.previous,root:$('cooking-panel'),listeners:[],pointer:null,pointers:new Set(),checkpoint:0,session:null,viewport:null};live=s;s.outcome=mountActivityOutcome($('cook-outcome'),{onRetry:()=>{apply(s,{type:'RESET'});s.root.querySelector('[data-cook-action=\"pour\"]').focus();},onExit:()=>ui.close()});try{s.session=createSession({...getActors(),zoneRoot:view.root,visual:view.homeView,reduced});s.viewport=createViewport({canvas:$('cook-canvas'),session:s.session,onFailure:()=>{if(live===s){s.state=reduceCooking(s.state,{type:'PAUSE'});s.renderFailed=true;save(s);render(s);$('cook-status').textContent='입체 화면이 멈췄어요. 나갔다 다시 열어 주세요';$('cook-render-note').hidden=false;}}});}catch{close();throw Error('Cooking setup failed');}
  bind(s,s.root,'click',e=>{const b=e.target.closest?.('[data-cook-action]');if(!b||!s.root.contains(b)||b.disabled||live!==s)return;const a=b.dataset.cookAction;if(a==='save'){save(s);render(s);return;}if(a==='recipe'||a==='reset')release(s);const action={type:a==='quadrant'?'STIR':a.toUpperCase(),id:b.dataset.id,index:Number(b.dataset.index),quadrant:Number(b.dataset.index),value:Number(b.dataset.value)};apply(s,action);});
  const pad=$('cook-stir-pad'),position=e=>{const r=pad.getBoundingClientRect(),x=e.clientX-r.left-r.width/2,y=e.clientY-r.top-r.height/2;if(Math.hypot(x,y)<r.width*.16)return;const q=(Math.round(Math.atan2(x,-y)/(Math.PI/2))+4)%4;apply(s,{type:'STIR',quadrant:q});};
  bind(s,pad,'pointerdown',e=>{if(live!==s||s.state.phase!=='mix'||e.button!==0)return;s.pointers.add(e.pointerId);if(s.pointers.size!==1||e.isPrimary===false){release(s);return;}s.pointer=e.pointerId;pad.setPointerCapture(e.pointerId);e.preventDefault();pad.focus();position(e);});bind(s,pad,'pointermove',e=>{if(s.pointer!==e.pointerId)return;e.preventDefault();position(e);});for(const type of ['pointerup','pointercancel','lostpointercapture'])bind(s,pad,type,e=>{s.pointers.delete(e.pointerId);if(s.pointer===e.pointerId)release(s);});bind(s,pad,'keydown',e=>{const q=['ArrowUp','ArrowRight','ArrowDown','ArrowLeft'].indexOf(e.key);if(q>=0){e.preventDefault();e.stopPropagation();if(!e.repeat)apply(s,{type:'STIR',quadrant:q});}});
  const pause=()=>{if(live!==s)return;release(s);s.state=reduceCooking(s.state,{type:'PAUSE'});save(s);render(s);};bind(s,win,'blur',pause);bind(s,doc,'visibilitychange',()=>{if(doc.hidden)pause();});$('cook-save').textContent=s.state.phase==='result'?'지난번에 완성한 요리를 불러왔어요.':s.state.order.length?'만들던 요리를 이어왔어요. 가열은 직접 시작해요.':'재료는 자유롭게 쓸 수 있어요. 만들던 요리는 자동으로 저장돼요.';render(s);return ()=>{if(live===s)close();};
 },{kind:'cooking-workshop',closeLabel:'나가기'});}
 return {open,close,get active(){return !!live;},tick(dt){const s=live;if(!s||doc.hidden)return;apply(s,{type:'TICK',dt});s.checkpoint+=dt;if(s.state.running&&s.checkpoint>=.5){s.checkpoint=0;save(s);}s.session?.tick(dt);s.viewport?.render();},snapshot(){return live?structuredClone(live.state):null;}};
}
